  check(tactics!=null&&tactics.available(),"optional tactics service loaded");if(phase.equals("restart")){resume();return;}
  var u=TownyUniverse.getInstance();u.newTownInternal("TacticsCity",T);u.newTownInternal("TacticsOther",D);town=TownyAPI.getInstance().getTown(T);var other=TownyAPI.getInstance().getTown(D);for(UUID person:people()){var r=u.getDataSource().newResident(actors.get(person).getName(),person);r.setTown(person.equals(X)?other:town);r.save();}town.setMayor(TownyAPI.getInstance().getResident(M));other.setMayor(TownyAPI.getInstance().getResident(X));var claim=new TownBlock(0,0,u.getWorld(world.getName()));u.addTownBlock(claim);claim.setTown(town);town.setHomeBlock(claim);claim.save();town.setSpawn(origin);town.save();other.save();
