 @SuppressWarnings("unchecked")void hold(String filename)throws Exception{var type=Class.forName("ru.neverland.core.AtomicFiles",true,owner.getClass().getClassLoader());var f=type.getDeclaredField("writers");f.setAccessible(true);var locks=(Map<Path,ReentrantLock>)f.get(null);var lock=locks.computeIfAbsent(owner.getDataFolder().toPath().resolve(filename).toAbsolutePath().normalize(),x->new ReentrantLock());release=new CountDownLatch(1);var entered=new CountDownLatch(1);new Thread(()->{lock.lock();entered.countDown();try{release.await(10,TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}finally{lock.unlock();}},"army-tactics-file-delay").start();if(!entered.await(1,TimeUnit.SECONDS))throw new AssertionError("writer lock unavailable");}
